/** @jest-environment node */
const { composite, contrast, hexToRgb, hslToRgb, luminance, oklchToRgb, utilityColor } = require('../scripts/check-color-contrast.js');

describe('independent sRGB palette arithmetic regression vectors', () => {
  // Values independently calculated from 8-bit hex with a Python reference,
  // not generated by the audit implementation or rounded before comparison.
  test.each([
    ['#FFFFFF', '#075C65', 7.69848420],
    ['#075C65', '#EFF8F6', 7.12214977],
    ['#14343D', '#EFF8F6', 12.23166773],
    ['#08252F', '#EF8D75', 6.63903627],
    ['#FFFFFF', '#EF8D75', 2.40358040],
    ['#08252F', '#F2C75C', 9.95392762],
    ['#FFFFFF', '#F2C75C', 1.60313175],
  ])('%s against %s matches an independent reference', (foreground, background, expected) => {
    expect(contrast(hexToRgb(foreground), hexToRgb(background))).toBeCloseTo(expected, 7);
  });

  it('normalizes HSL hue and validates colors instead of silently producing NaN', () => {
    expect(hexToRgb('#0fA')).toEqual([0, 1, 170 / 255]);
    expect(hslToRgb('360 100% 50%')).toEqual(hslToRgb('0 100% 50%'));
    expect(hslToRgb('-120 100% 50%')).toEqual(hslToRgb('240 100% 50%'));
    for (const color of ['1 101% 50%', '1 10% 101%', 'red', 'NaN 1% 1%']) {
      expect(() => hslToRgb(color)).toThrow();
    }
    for (const color of ['#ffff', '#gggggg', '#000000ff']) expect(() => hexToRgb(color)).toThrow();
  });

  it('exercises both sides of the sRGB transfer threshold without using rounded ratios', () => {
    const below = 0.04044;
    const above = 0.04046;
    expect(luminance([below, below, below])).toBeCloseTo(below / 12.92, 12);
    expect(luminance([above, above, above])).toBeCloseTo(((above + 0.055) / 1.055) ** 2.4, 12);
    expect(contrast(hexToRgb('#777777'), hexToRgb('#FFFFFF'))).toBeLessThan(4.5);
    expect(contrast(hexToRgb('#767676'), hexToRgb('#FFFFFF'))).toBeGreaterThan(4.5);
  });

  it('converts in-gamut OKLCH primaries and equivalent lightness units', () => {
    const red = oklchToRgb('oklch(62.795536% 0.2576833 29.233885)');
    red.forEach((channel, index) => expect(channel).toBeCloseTo(index === 0 ? 1 : 0, 5));
    expect(oklchToRgb('oklch(0.5 0 0)')).toEqual(oklchToRgb('oklch(50% 0 0)'));
    expect(() => oklchToRgb('oklch(101% 0 0)')).toThrow();
  });

  it('composites translucent foreground over the resolved background before luminance', () => {
    const card = hexToRgb('#FFFFFF');
    const selected = composite(hexToRgb('#075C65'), card, 0.1);
    const foreground = composite(hexToRgb('#14343D'), selected, 0.8);
    [0.9027450980392157, 0.9360784313725491, 0.939607843137255].forEach((channel, index) => {
      expect(selected[index]).toBeCloseTo(channel, 12);
    });
    // Independent reference includes BOTH alpha layers over an opaque card.
    expect(contrast(foreground, selected)).toBeCloseTo(6.3672459194, 7);
    expect(composite([1, 0, 0], card, 0)).toEqual(card);
    expect(composite([1, 0, 0], card, 1)).toEqual([1, 0, 0]);
    for (const opacity of [-0.1, 1.1, NaN]) expect(() => composite(card, card, opacity)).toThrow();
  });

  it('chooses dark color overrides regardless of class attribute order', () => {
    expect(utilityColor('dark:text-green-400 text-sm text-green-700', 'text', 'dark')).toBe('green-400');
    expect(utilityColor('dark:text-green-400 text-sm text-green-700', 'text', 'light')).toBe('green-700');
    expect(utilityColor('text-xl/7 text-center text-foreground', 'text', 'dark')).toBe('foreground');
    expect(() => utilityColor('text-primary text-destructive', 'text', 'light')).toThrow('Ambiguous');
    expect(() => utilityColor('text-sm text-center', 'text', 'light')).toThrow('Missing');
  });
});
